import{_ as t,o as a,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const i="/eep/ini-edit-translate-2026/editor-en.png",f=JSON.parse('{"title":"INI Edit Translate 2026","description":"Features of the Windows editor for EEP model INI files and Installation.eep with ChatGPT translation.","frontmatter":{"title":"INI Edit Translate 2026","description":"Features of the Windows editor for EEP model INI files and Installation.eep with ChatGPT translation."},"headers":[],"relativePath":"en/eep/ini-edit-translate-2026/index.md","filePath":"en/eep/ini-edit-translate-2026/index.md","lastUpdated":1792754903000}'),o={name:"en/eep/ini-edit-translate-2026/index.md"};function s(d,e,l,c,p,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><p><strong>Version 2.1.35.0 · Windows 11 · .NET Framework 4.8</strong></p><p>Edit EEP model descriptions and installation files. Developed by Uwe Grimm / UGSo Software and published under the MIT licence.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Source code and README on GitHub</a></p><p><img src="'+i+'" alt="Reviewed English application interface without personal data"></p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/download/v2.1.35/INI-Edit-Translate-2026-v2.1.35-windows.zip" target="_blank" rel="noreferrer">Download Windows ZIP v2.1.35</a> · <a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/tag/v2.1.35" target="_blank" rel="noreferrer">GitHub release and SHA-256</a></p><p>Extract the complete ZIP and run <code>INI Edit Translate 2026.exe</code>. Requires Windows 11 and .NET Framework 4.8. Keep DLLs and language folders together. Visual Studio is only needed to build from source. No installer is required.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Capabilities</th></tr></thead><tbody><tr><td>Model texts</td><td>Edit names and descriptions in EN/DE/FR/PL</td></tr><tr><td>Metadata</td><td>Edit PDF references, generation, deployment years, country and icon</td></tr><tr><td>Movement axes and signal functions</td><td>Display, edit and translate language-specific entries</td></tr><tr><td>Installation.eep</td><td>Edit names and descriptions of supported installation sections</td></tr><tr><td>Preview</td><td>Compare the original file with the generated output preview</td></tr><tr><td>Table export</td><td>Export complete tables as tab-separated UTF-8 files with a BOM</td></tr><tr><td>Backups</td><td>Copy existing INI files before overwriting them, retaining their original filename</td></tr></tbody></table><h2 id="chatgpt-translation" tabindex="-1">ChatGPT translation <a class="header-anchor" href="#chatgpt-translation" aria-label="Permalink to &quot;ChatGPT translation&quot;">​</a></h2><p>The application uses only the OpenAI Responses API. Each source text is translated into the three other target languages in one request, without an English intermediate translation. Repeated texts share a temporary cache within the same operation.</p><p>The progress dialog provides <strong>Cancel</strong>. The request timeout is 60 seconds; each text is limited to 24,000 characters. Incomplete responses, missing languages and changed placeholders such as <code>{0}</code>, <code>%s</code> or <code>[e]</code> are rejected. Existing texts and tables are preserved on failure.</p><p>DE/EN/FR interface texts have been reviewed for broken characters, wrong-language entries and mixed messages. Technical INI keys such as <code>Name_GER</code> are retained.</p><h2 id="setup-and-workflow" tabindex="-1">Setup and workflow <a class="header-anchor" href="#setup-and-workflow" aria-label="Permalink to &quot;Setup and workflow&quot;">​</a></h2><ol><li>Download the Windows ZIP above and extract all files.</li><li>Start <code>INI Edit Translate 2026.exe</code> from the extracted directory, keeping its DLLs and language directories together.</li><li>Open <strong>About → Settings → OpenAI translation</strong>. Enter your own API key and model; the default is <code>gpt-4.1-mini</code>.</li><li>Open a backed-up file in <strong>Read only</strong> mode first.</li><li>Use <strong>Read and translate</strong> or a translation button. Select the source language for axes and signal functions.</li><li>Review the preview and model texts, then save explicitly.</li></ol><h2 id="data-and-privacy" tabindex="-1">Data and privacy <a class="header-anchor" href="#data-and-privacy" aria-label="Permalink to &quot;Data and privacy&quot;">​</a></h2><p>Old registrations and personal databases are not imported. Settings are stored separately for each Windows user. OpenAI configuration and file backups are under <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Windows DPAPI encrypts the API key for the current Windows account. Selected texts are sent to OpenAI with <code>store: false</code>. Internet access and separate API billing are required; a ChatGPT subscription does not replace API billing.</p><h2 id="updates-and-verification" tabindex="-1">Updates and verification <a class="header-anchor" href="#updates-and-verification" aria-label="Permalink to &quot;Updates and verification&quot;">​</a></h2><p><strong>Updates are currently fully disabled:</strong> no connection to the old update server and no update menu. Google, LEO, Linguee and DeepL are no longer offered.</p><p>30 local checks with mocked API responses and Debug/Release builds cover failures, cancellation, restoration, export and rendered DE/EN/FR interfaces. Tests do not send texts to OpenAI. A live API request and generated translation quality still need verification with your own account. Not every possible INI schema is supported; review the resulting model data before use.</p>',22)])])}const g=t(o,[["render",s]]);export{f as __pageData,g as default};
